#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXE 10005
#define MAXR 40005
#define MAXHEAP 40005
#define INF 1000000000000000000LL

typedef struct {
    int v;
    long long d;
} Node;

int E, R;
int head[MAXE];
int to[MAXR];
int weight[MAXR];
int next[MAXR];
int edge_cnt = 0;

void add_edge(int u, int v, int w) {
    to[edge_cnt] = v;
    weight[edge_cnt] = w;
    next[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

int visited[MAXE];
int parent[MAXE];
int depth[MAXE];
int weight_to_parent[MAXE];
int cycle_id[MAXE];
int cycle_length[MAXE];
int cycle_count = 0;

void dfs(int u, int p, int d, int w_from_parent) {
    visited[u] = 1;
    parent[u] = p;
    depth[u] = d;
    weight_to_parent[u] = w_from_parent;
    for (int e = head[u]; e != -1; e = next[e]) {
        int v = to[e];
        int w = weight[e];
        if (v == p) continue;
        if (!visited[v]) {
            dfs(v, u, d + 1, w);
        } else if (depth[v] < depth[u]) {
            int cid = cycle_count++;
            int len = w;
            int cur = u;
            while (cur != v) {
                cycle_id[cur] = cid;
                len += weight_to_parent[cur];
                cur = parent[cur];
            }
            cycle_id[v] = cid;
            cycle_length[cid] = len;
        }
    }
}

Node heap[MAXHEAP];
int heap_size = 0;

void heap_push(int v, long long d) {
    int i = ++heap_size;
    while (i > 1 && heap[i / 2].d > d) {
        heap[i] = heap[i / 2];
        i /= 2;
    }
    heap[i].v = v;
    heap[i].d = d;
}

Node heap_pop() {
    Node ret = heap[1];
    heap[1] = heap[heap_size--];
    int i = 1;
    while (1) {
        int left = i * 2, right = i * 2 + 1, smallest = i;
        if (left <= heap_size && heap[left].d < heap[smallest].d) smallest = left;
        if (right <= heap_size && heap[right].d < heap[smallest].d) smallest = right;
        if (smallest == i) break;
        Node tmp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = tmp;
        i = smallest;
    }
    return ret;
}

int main(void) {
    if (scanf("%d %d", &E, &R) != 2) return 0;

    for (int i = 1; i <= E; i++) {
        head[i] = -1;
        cycle_id[i] = -1;
    }

    for (int i = 0; i < R; i++) {
        int A, B, C;
        scanf("%d %d %d", &A, &B, &C);
        add_edge(A, B, C);
        add_edge(B, A, C);
    }

    for (int i = 1; i <= E; i++) {
        if (!visited[i]) {
            dfs(i, 0, 0, 0);
        }
    }

    int K;
    scanf("%d", &K);

    long long dist[MAXE];
    long long min_dist[MAXE];

    for (int q = 0; q < K; q++) {
        int X, T;
        scanf("%d %d", &X, &T);

        for (int i = 1; i <= E; i++) {
            dist[i] = INF;
        }
        dist[X] = 0;
        heap_size = 0;
        heap_push(X, 0);

        while (heap_size > 0) {
            Node node = heap_pop();
            int u = node.v;
            long long d = node.d;
            if (d > dist[u]) continue;
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                int w = weight[e];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    heap_push(v, dist[v]);
                }
            }
        }

        for (int i = 0; i < cycle_count; i++) {
            min_dist[i] = INF;
        }

        for (int v = 1; v <= E; v++) {
            if (cycle_id[v] != -1) {
                int c = cycle_id[v];
                if (dist[v] < min_dist[c]) {
                    min_dist[c] = dist[v];
                }
            }
        }

        long long ans = INF;
        for (int c = 0; c < cycle_count; c++) {
            if (cycle_length[c] >= T) {
                if (min_dist[c] < INF) {
                    long long total = 2 * min_dist[c] + cycle_length[c];
                    if (total < ans) ans = total;
                }
            }
        }

        if (ans == INF) {
            printf("-1\n");
        } else {
            printf("%lld\n", ans);
        }
    }

    return 0;
}
